head.script:

	scwin.onpageload = function() {

	};

	scwin.onpageunload = function() {
	};

	scwin.addWindow1_onclick = function(e) {
		scwin.addWindow("1");
	};

	scwin.addWindow = function(windowIdx) {
//		windowContainer1.createWindow( "Window<img src=1 onerror=alert(document.cookie)>" + windowIdx , null , "sub" + windowIdx + ".xml" );
		console.log("test");
		var obj = {
		        "title" : "Window<img src=1 onerror=>", 
				//"title" : "Window<img src=1 onerror=alert(document.cookie)>", 
		        "windowID": "001", 
//		        "frameMode" : "wframe", 
		        "src" : "windowContainer_escape_WESD-906_(WSQ-4874)_subFrm.xml"
		        };

		windowContainer1.createWindow(obj);
	};

	scwin.checkVal = function(){
		return WebSquare.wUnit.getDomById('windowContainer1_subWindow0_header_title').getElementsByTagName('img').length == 1;
	};

	scwin.unitTest = function(){
		//Unit test
		WebSquare.wUnit.start();

		WebSquare.wUnit.addCommand("pause", "1500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('addWindow1').click()");
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal()","true");
		WebSquare.wUnit.addCommand("pause", "500");

		//Run and Stop test
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}
	scwin.unitTest();
